use crate::{models::{DeployInput,DeployResult},processes::ProcessRegistry,workspace};
use std::process::Command;
use tauri::{AppHandle,State};

fn run(exe:&str,args:&[String])->Result<String,String>{let out=Command::new(exe).args(args).output().map_err(|e|format!("Unable to execute {exe}: {e}"))?;let stdout=String::from_utf8_lossy(&out.stdout).to_string();let stderr=String::from_utf8_lossy(&out.stderr).to_string();if out.status.success(){Ok(if stdout.trim().is_empty(){stderr}else{stdout})}else{Err(if stderr.trim().is_empty(){stdout}else{stderr})}}
fn validate(input:&DeployInput)->Result<(),String>{
    let host=input.host.trim();
    let user=input.username.trim();
    let remote=input.remote_path.trim();
    if host.is_empty()||user.is_empty(){return Err("Host and username are required.".into())}
    if !host.chars().all(|c|c.is_ascii_alphanumeric()||matches!(c,'.'|'-'|':'|'['|']')){return Err("Host contains unsupported characters.".into())}
    if !user.chars().all(|c|c.is_ascii_alphanumeric()||matches!(c,'.'|'_'|'-'|'@')){return Err("Username contains unsupported characters.".into())}
    if remote.is_empty()||remote.contains("..")||!remote.chars().all(|c|c.is_ascii_alphanumeric()||matches!(c,'/'|'\\'|'.'|'_'|'-')){return Err("Remote path is invalid or unsafe.".into())}
    if input.kind=="connector"&&!(input.site_url.starts_with("https://")||input.site_url.starts_with("http://")){return Err("Connector site URL must start with http:// or https://.".into())}
    Ok(())
}
pub fn test(input:&DeployInput)->Result<DeployResult,String>{validate(input)?;let kind=input.kind.to_ascii_lowercase();let message=match kind.as_str(){"ssh"=>run("ssh",&vec!["-p".into(),input.port.unwrap_or(22).to_string(),format!("{}@{}",input.username,input.host),"printf PINWP_OK".into()])?,"cpanel"=>run("curl.exe",&vec!["-fsS".into(),"-H".into(),format!("Authorization: cpanel {}:{}",input.username,input.secret),format!("https://{}:{}/execute/Variables/get_server_information",input.host,input.port.unwrap_or(2083))])?,"connector"=>run("curl.exe",&vec!["-fsS".into(),"-u".into(),format!("{}:{}",input.username,input.secret),format!("{}/wp-json/pinwp/v1/health",input.site_url.trim_end_matches('/'))])?,_=>return Err("Unknown deployment adapter.".into())};Ok(DeployResult{success:true,stage:"connection-test".into(),message,artifact_path:None})}
pub fn deploy(app:&AppHandle,state:&State<'_,ProcessRegistry>,input:&DeployInput)->Result<DeployResult,String>{validate(input)?;let archive=workspace::export_site(app,state,&input.site_id)?;let kind=input.kind.to_ascii_lowercase();let message=match kind.as_str(){"ssh"=>{let target=format!("{}@{}",input.username,input.host);let port=input.port.unwrap_or(22).to_string();let remote=input.remote_path.trim_end_matches('/');run("ssh",&vec!["-p".into(),port.clone(),target.clone(),format!("mkdir -p '{remote}/.pinwp-backups' && if [ -d '{remote}/wp-content' ]; then tar -czf '{remote}/.pinwp-backups/pre-pinwp-$(date +%Y%m%d-%H%M%S).tgz' -C '{remote}' .; fi")])?;run("scp",&vec!["-P".into(),port.clone(),archive.clone(),format!("{target}:{remote}/pinwp-deploy.zip")])?;run("ssh",&vec!["-p".into(),port,target,format!("cd '{remote}' && rm -rf .pinwp-deploy && mkdir .pinwp-deploy && unzip -oq pinwp-deploy.zip -d .pinwp-deploy && cp -a .pinwp-deploy/public/. . && rm -rf .pinwp-deploy pinwp-deploy.zip")])?},"cpanel"=>run("curl.exe",&vec!["-fsS".into(),"-H".into(),format!("Authorization: cpanel {}:{}",input.username,input.secret),"-F".into(),format!("dir={}",input.remote_path),"-F".into(),format!("file-1=@{archive}"),format!("https://{}:{}/execute/Fileman/upload_files",input.host,input.port.unwrap_or(2083))])?,"connector"=>run("curl.exe",&vec!["-fsS".into(),"-u".into(),format!("{}:{}",input.username,input.secret),"-F".into(),format!("package=@{archive}"),format!("{}/wp-json/pinwp/v1/deploy",input.site_url.trim_end_matches('/'))])?,_=>return Err("Unknown deployment adapter.".into())};Ok(DeployResult{success:true,stage:"deploy".into(),message,artifact_path:Some(archive)})}
